sys_script_include.script:
var DependentUtil = Class.create();
DependentUtil.prototype = {
    initialize: function() {
        this.DEPENDTENTS_TABLE = "x_1806928_health_0_dependents_info";
        this.USER_TABLE = "sys_user";
        this.FAILED = "FAILED";
        this.SUCCESS = "SUCCESS";
    },

    returnSysID: function(queryInput, table) {

        var sysID = "";

        if (queryInput && table) {
            var grInfo = new GlideRecord(table);
            grInfo.addEncodedQuery(queryInput);
            grInfo.query();
            if (grInfo.next()) {
                sysID = grInfo.getValue("sys_id");
                return sysID;
            } else {
                return sysID;
            }
        } else {
            return sysID;
        }
    },

    addDependentInfo: function(infoObj) {

        var output = {};
        output.status = this.FAILED;
        output.message = "";
        var name = infoObj.name;
        var rel = infoObj.relationship;
        var age = infoObj.age;
        var user = infoObj.primaryInsured;
        var userID = this.returnSysID("name=" + user, this.USER_TABLE);
        var dpQuery = "name=" + name + "^relationship=" + rel + "^age=" + age + "^primary_insured=" + userID;
        var dependentCheck = this.returnSysID(dpQuery, this.DEPENDTENTS_TABLE);

        if (!dependentCheck) {
            var addDependentInfo = new GlideRecord(this.DEPENDTENTS_TABLE);
            addDependentInfo.initialize();
            addDependentInfo.name = name;
            addDependentInfo.relationship = rel;
            addDependentInfo.age = age;
            addDependentInfo.primary_insured = user;
            var check = addDependentInfo.insert();
            if (check) {
                output.status = this.SUCCESS;
                output.message = "Dependent info inserted successfully";
            } else {
                output.status = this.FAILED;
                output.message = "Dependent info insert failed";
            }

            return output;

        } else {
            output.status = this.FAILED;
            output.message = "Duplicate Depedent info cannot be inserted";
            return output;
        }
    },

    type: 'DependentUtil'
};
